interface UserCache {
    /** Stores the user; a later get(id) may return it. */
    fun put(user: User)
    fun get(id: String): User?
}

class InMemoryUserCache : UserCache {
    private val map = mutableMapOf<String, User>()
    override fun put(user: User) { map[user.id] = user }
    override fun get(id: String) = map[id]
}

class BoundedUserCache(private val maxSize: Int) : UserCache {
    private val map = LinkedHashMap<String, User>()
    override fun put(user: User) {
        check(map.size < maxSize) { "Cache is full" }
        map[user.id] = user
    }
    override fun get(id: String) = map[id]
}
